pub const HELP_REPL_SET_STEP_DOWN: &str = "{ replSetStepDown : <seconds> }\nStep down as primary.  Will not try to reelect self for the specified time period (1 minute if no numeric secs value specified, or secs is 0).\n(If another member with same priority takes over in the meantime, it will stay primary.)\nhttp://dochub.mongodb.org/core/replicasetcommands";

/// The `listCommands` help of `setFeatureCompatibilityVersion`.
pub const HELP_SET_FEATURE_COMPATIBILITY_VERSION: &str = "Set the featureCompatibilityVersion used by this cluster. If set to '8.0', then features introduced in versions greater than '8.0' will be disabled If set to '8.3', then features introduced in '9.0' will be disabled. If set to '9.0', then '9.0' features are enabled, and all nodes in the cluster must be binary version 9.0. See https://docs.mongodb.com/master/release-notes/8.0-compatibility/#feature-compatibility.";

