/// A mark `${name:X}` whose `X` is not a constant of this crate.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UnknownName(pub String);

impl std::fmt::Display for UnknownName {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "unknown name mark ${{name:{}}}", self.0)
    }
}

impl std::error::Error for UnknownName {}

/// The opening of a mark.
const OPEN: &str = "${name:";

/// `text` with every mark `${name:X}` replaced by the constant `X`: test data and data files keep the marks, so that
/// only this crate holds the literals.
///
/// # Errors
///
/// [`UnknownName`] for a mark that names no constant.
pub fn expand(text: &str) -> Result<String, UnknownName> {
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(at) = rest.find(OPEN) {
        let after = &rest[at + OPEN.len()..];
        let Some(end) = after.find('}') else { break };
        let name = &after[..end];
        let value = ALL
            .iter()
            .find(|(n, _)| *n == name)
            .map(|(_, v)| *v)
            .ok_or_else(|| UnknownName(name.to_owned()))?;
        out.push_str(&rest[..at]);
        out.push_str(value);
        rest = &after[end + 1..];
    }
    out.push_str(rest);
    Ok(out)
}

/// [`expand`] for text that lives as long as the program, such as `include_str!` of test data: the same text when it
/// has no marks, and otherwise the expanded copy, kept for the rest of the run.
///
/// # Panics
///
/// On a mark that names no constant, which is a defect of the data.
#[must_use]
pub fn expand_static(text: &'static str) -> &'static str {
    if !text.contains(OPEN) {
        return text;
    }
    match expand(text) {
        Ok(expanded) => Box::leak(expanded.into_boxed_str()),
        Err(e) => panic!("{e}"),
    }
}
